  `name` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `radical` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `origins` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
